CREATE TABLE public.social_examples(id text PRIMARY KEY,kind text NOT NULL CHECK(kind IN('friend','request','invite','nudge','message')),name text NOT NULL,title text NOT NULL,body text NOT NULL DEFAULT '',photo text,plan_id uuid REFERENCES public.plans(id) ON DELETE SET NULL); GRANT SELECT ON public.social_examples TO anon,authenticated; GRANT ALL ON public.social_examples TO service_role; ALTER TABLE public.social_examples ENABLE ROW LEVEL SECURITY; CREATE POLICY "read fictional social examples" ON public.social_examples FOR SELECT TO anon,authenticated USING(true);